phase = 'fwd'
tstart = None

def control(obs):
    global phase, tstart
    t = obs['t']
    h = obs['hitch_deg']
    st = obs['status']
    if tstart is None:
        tstart = t
    if st in ('PINNED', 'JACKKNIFED') and phase == 'rev':
        phase = 'fwd'
        tstart = t
    if phase == 'fwd':
        if t - tstart < 2.5:
            return {'steer_deg': 15.0, 'speed_mps': 0.6, 'look_deg': 0}
        phase = 'rev'
        tstart = t
    steer = 3.0 * (h - 2.0)
    steer = max(-30.0, min(30.0, steer))
    return {'steer_deg': steer, 'speed_mps': -0.4, 'look_deg': 180}

