state = {'phase': 'fwd', 't0': None, 'ph': None, 'pt': None}

def control(obs):
    t = obs['t']
    h = obs['hitch_deg']
    st = obs['status']
    y = obs['rig']['trailer_rear'][1]
    if state['t0'] is None:
        state['t0'] = t
        state['pt'] = t
        state['ph'] = h
    if st in ('PINNED', 'JACKKNIFED') and state['phase'] == 'rev':
        state['phase'] = 'fwd'
        state['t0'] = t
    if state['phase'] == 'fwd':
        if t - state['t0'] < 4.0:
            return {'steer_deg': 0.0, 'speed_mps': 0.5, 'look_deg': 0}
        state['phase'] = 'rev'
        state['pt'] = t
        state['ph'] = h
    dt = t - state['pt']
    dh = (h - state['ph']) / dt if dt > 1e-3 else 0.0
    state['pt'] = t
    state['ph'] = h
    steer = 3.0 * h + 0.5 * dh + 3.0 * (y - 0.5)
    steer = max(-20.0, min(20.0, steer))
    return {'steer_deg': steer, 'speed_mps': -0.3, 'look_deg': 180}

